/* TRIBUNAL V — identidade, investigação e audiência.
   Regras de gameplay são separadas dos fatos canônicos e dos fundamentos. */
(()=>{
'use strict';
const previous={render,accept,selected,dossier,caseHeader,overview,evidencePage,interviewsPage,hearingPage,office,caseCard,casesPage,decisionPage,revealNext,closeInstruction:window.closeInstruction,startHearing,importProgress:window.importProgress,askSuggested:window.askSuggested,askOral:window.askOral,chat};
const norm=x=>String(x||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const money=n=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:0}).format(n||0);
const short=(x,n=160)=>String(x||'').length>n?String(x).slice(0,n).replace(/\s+\S*$/,'')+'…':String(x||'');
const flow=(p,c)=>window.__TRIBUNAL_SIM3__.flow(p,c);
const ui={page:1,readerId:null,search:'',boardFact:null,noteOpen:false,challenge:null,timer:null,drawing:false,lastMode:''};
const T=window.T5=window.Tribunal5={};
const hasCareer=!!s.v5;
s.v5={version:5,officeLevel:0,upgrades:{},publicApproval:50,ethics:50,specialties:{},sound:false,music:false,volume:35,timed:false,largeText:false,contrast:false,news:[],rewarded:[],...(s.v5||{})};
if(!hasCareer&&!Object.keys(s.cases).length&&s.day===1&&s.cash===185420)s.cash=12500;
function game(c=iCur(),p=pCur()){
 if(!p||!c)return null;
 p.v5={version:5,notes:'',pins:[],highlights:[],connections:[],positions:{},drafts:{},credibility:65,attention:70,objections:3,questionKeys:[],confrontKeys:[],moods:{},closing:null,ethicalChoice:null,consulted:false,challengeIndex:0,challengeHistory:[],lastAnswer:null,seen:[],...(p.v5||{})};
 return p.v5;
}
function safeRefresh(scroll=false){refresh(scroll);}
function addLog(p,text){recordCaseHistory(p,text);}
const drafts=['petition','courtSpeech','counterText','oralQuestion','ask','reviewGrounds','expName','expValue','expShare','closingArgument','connectionConclusion','confrontReason'];
function capture(){const g=game();if(!g)return;for(const id of drafts){let el=$(id);if(el&&el.type!=='checkbox')g.drafts[id]=el.value;}}
function restore(){const g=game();if(!g)return;for(const [id,value] of Object.entries(g.drafts)){const el=$(id);if(el&&document.activeElement!==el)el.value=value;}}
let saveTimer;
document.addEventListener('input',e=>{if(drafts.includes(e.target.id)){let g=game();if(g){g.drafts[e.target.id]=e.target.value;clearTimeout(saveTimer);saveTimer=setTimeout(store,350);}}});
window.addEventListener('beforeunload',()=>{capture();store();});
const provider=window.__CASE_PROVIDER__;
async function ready(id){let c=get(id);if(!c)throw Error('Caso não encontrado.');if(provider?.modular&&!c._loaded)c=await provider.load(id);return c;}
accept=async function(id){try{const c=await ready(id);previous.accept(id);game(c,s.cases[id]);Audio.fx('paper');safeRefresh();}catch(e){toast('Não foi possível abrir o dossiê. Tente novamente.');}};
selected=function(id,tab='resumo'){capture();const open=()=>{ui.skipCapture=true;ui.readerId=null;ui.boardFact=null;ui.challenge=null;stopClock();previous.selected(id,tab);game();Audio.fx('paper');};if(get(id)?._loaded){open();return Promise.resolve();}return ready(id).then(open).catch(()=>toast('Não foi possível carregar este caso.'));};
for(const c of CASES)if(s.cases[c.id]&&c._loaded)game(c,s.cases[c.id]);

const Audio={ctx:null,ambient:null,
 init(){if(!this.ctx){const C=window.AudioContext||window.webkitAudioContext;if(!C)return null;this.ctx=new C();}if(this.ctx.state==='suspended')this.ctx.resume().catch(()=>{});return this.ctx;},
 fx(kind){if(!s.v5.sound||!this.ctx||this.ctx.state!=='running')return;const ctx=this.ctx,t=ctx.currentTime,volume=s.v5.volume/100*.14;const duration=kind==='gavel'?.32:kind==='paper'?.17:kind==='stamp'?.11:.025;
  const gain=ctx.createGain();gain.gain.setValueAtTime(volume,t);gain.gain.exponentialRampToValueAtTime(.0001,t+duration);gain.connect(ctx.destination);
  if(kind==='paper'||kind==='stamp'||kind==='click'||kind==='type'){const buffer=ctx.createBuffer(1,ctx.sampleRate*duration,ctx.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=(Math.random()*2-1)*(1-i/data.length);const src=ctx.createBufferSource();src.buffer=buffer;const filter=ctx.createBiquadFilter();filter.type='bandpass';filter.frequency.value=kind==='paper'?1700:750;src.connect(filter);filter.connect(gain);src.start(t);src.stop(t+duration);}else{const osc=ctx.createOscillator();osc.type='triangle';osc.frequency.setValueAtTime(120,t);osc.frequency.exponentialRampToValueAtTime(40,t+duration);osc.connect(gain);osc.start(t);osc.stop(t+duration);}},
 chord(){if(!s.v5.music||!this.ctx||this.ctx.state!=='running')return;const ctx=this.ctx,t=ctx.currentTime,hearing=!!pCur()?.workflow?.hearingOpened;let notes=hearing?[110,130.81,164.81]:[110,164.81,220];for(const [i,hz] of notes.entries()){let o=ctx.createOscillator(),g=ctx.createGain();o.type='sine';o.frequency.value=hz;o.detune.value=i%2?4:-3;g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(s.v5.volume/100*.018,t+.9+i*.1);g.gain.exponentialRampToValueAtTime(.0001,t+4.8);o.connect(g);g.connect(ctx.destination);o.start(t);o.stop(t+5);}},
 ambientStart(){this.init();clearInterval(this.ambient);if(s.v5.music){this.chord();this.ambient=setInterval(()=>this.chord(),5400);}},
 stop(){clearInterval(this.ambient);this.ambient=null;}
};
T.toggleSound=()=>{s.v5.sound=!s.v5.sound;if(s.v5.sound){Audio.init();Audio.fx('stamp');}safeRefresh();toast(s.v5.sound?'Efeitos sonoros ligados.':'Efeitos sonoros desligados.');};
document.addEventListener('click',e=>{if(e.target.closest('button')&&!e.target.closest('[data-no-sound]'))Audio.fx('click');});
T.settings=()=>{closeModal();document.body.insertAdjacentHTML('beforeend',`<div class="modalbg" id="docModal"><div class="modal"><div class="rows between"><div><div class="eyebrow">PREFERÊNCIAS DO JOGADOR</div><h3>Seu ritmo de investigação</h3></div><button class="btn sm" onclick="closeModal()">Fechar ✕</button></div>${[['sound','Efeitos mecânicos de papel, carimbo e martelo'],['music','Ambiente musical procedural'],['timed','Desafios de objeção com cronômetro de 25 segundos'],['largeText','Texto ampliado'],['contrast','Contraste reforçado']].map(([key,label])=>`<label class="v5-settings-row"><input type="checkbox" ${s.v5[key]?'checked':''} onchange="T5.setting('${key}',this.checked)"><span>${label}</span></label>`).join('')}<div class="field" style="margin-top:17px"><label>Volume</label><input type="range" min="5" max="70" value="${s.v5.volume}" oninput="T5.setting('volume',Number(this.value))"></div><p class="v5-legalnotice">O cronômetro vem desligado. Leitura, caderno e pesquisa não consomem tempo nem atenção. Você pode acelerar diálogos sem penalidade.</p></div></div>`);};
T.setting=(key,value)=>{if(!['sound','music','timed','largeText','contrast','volume'].includes(key))return;s.v5[key]=value;if(key==='music'){if(value)Audio.ambientStart();else Audio.stop();}if(key==='sound'&&value)Audio.init();if(key==='timed'&&!value){stopClock();if(ui.challenge)ui.challenge.remaining=null;}applyPrefs();store();};
function applyPrefs(){document.body.classList.toggle('v5-large-text',s.v5.largeText);document.body.classList.toggle('v5-high-contrast',s.v5.contrast);}
function empty(label){return `<div class="v5-empty">${es(label)}</div>`;}
function folderCard(c){let p=s.cases[c.id],g=p?.v5,outcome=p?.decision?__TRIBUNAL_V4__.outcome(p.decision):null;let status=outcome?({favoravel:'Favorável',parcial:'Parcial',desfavoravel:'Desfavorável'})[outcome]:p?.reviewActive?'Em reanálise':p?.v7?.accepted===false?'Em contratação':p?'Em andamento':'Novo dossiê';return `<article class="v5-case" data-area="${es(c.area)}"><div class="v5-case-top"><div><span class="v5-case-id">${es(c.id.replace('CASO-','AUTOS Nº '))}</span><br><span class="tag ${outcome==='desfavoravel'?'red':outcome?'green':'gold'}">${es(status)}</span></div><img class="v5-case-portrait" loading="lazy" src="${c.cover||tribunalPortrait(c.id+'-T1')}" alt="Retrato vetorial noir de ${es(c.client)}"></div><span class="v5-case-id">${es(c.kind)}</span><h3 class="v5-case-title">${es(c.title)}</h3><span class="v5-mobile-status tag ${outcome==='desfavoravel'?'red':outcome?'green':'gold'}">${es(status)}</span><p>${es(c.summary||c.claim)}</p><div class="v5-case-meta"><span class="v5-difficulty">${Array.from({length:5},(_,i)=>`<i class="${i<c.difficulty?'on':''}"></i>`).join('')} &nbsp; ${c.difficulty<=2?'INICIAL':c.difficulty===3?'INTERMEDIÁRIO':'COMPLEXO'}</span><button class="v5-open" onclick="${p?'selected':'accept'}('${c.id}')">Abrir pasta ↗</button></div></article>`;}
caseCard=folderCard;
dashboard=function(){let played=CASES.filter(c=>s.cases[c.id]),active=played.filter(c=>!s.cases[c.id].decision),suggested=(active.length?active:CASES.filter(c=>!s.cases[c.id])).slice(0,3),events=[];for(const c of played){for(const e of s.cases[c.id].workflow?.events||[])if(!e.done)events.push({...e,title:c.title,id:c.id});}events.sort((a,b)=>a.day-b.day);return `<div class="v5-home"><div class="v5-opening"><div class="v5-issue">ESCRITÓRIO DE ADVOCACIA · ARQUIVO PESSOAL</div><span class="v5-date">EDIÇÃO VI / ${es(__TRIBUNAL_SIM3__.dateOf(s.day))}</span></div><section class="v5-hero"><div class="v5-hero-copy"><div class="eyebrow">ENTRE FATOS E VERSÕES</div><h1>Toda versão<br>deixa uma pista.</h1><p>Escute o que foi dito. Encontre o que foi omitido.<br>Construa a defesa que os fatos permitem.</p><div class="rows"><button class="btn primary" onclick="nav('casos')">Explorar os 100 casos &nbsp; ↗</button><button class="v5-textbtn" onclick="nav('processos')">Continuar investigação</button></div></div><div class="v5-hero-art" aria-hidden="true"><div class="v5-folder"></div><div class="v5-file"><span>TRIBUNAL · DOCUMENTO FICCIONAL</span><strong>A verdade não cabe<br>em uma única versão.</strong><hr><hr><hr><hr><hr><div class="stamp">CONFIDENCIAL</div></div><div class="v5-clip"></div><div class="v5-paper-note">O detalhe que falta<br>pode mudar tudo.</div></div></section><div class="v5-sectionhead"><h2>${active.length?'Sobre sua mesa':'Primeiras investigações'}</h2><button class="v5-textbtn" onclick="nav('casos')">Ver todos os dossiês ↗</button></div><div class="v5-foldergrid">${suggested.map(folderCard).join('')}</div><div class="v5-split"><section class="v5-ledger"><h3>Próximos compromissos</h3>${events.slice(0,4).map(e=>`<div class="v5-ledger-row"><span class="v5-bullet"></span><div><b>${es(e.title)}</b><br><small>Dia ${e.day} · ${es(e.detail||e.type)}</small></div><button class="v5-textbtn" style="margin-left:auto" onclick="selected('${e.id}','andamentos')">Abrir</button></div>`).join('')||`<div class="v5-ledger-row"><span class="v5-bullet"></span><div>${played.length?'Nenhum ato agendado neste momento.<br><small>Consulte suas pastas e protocole a manifestação para iniciar a tramitação.</small>':'Seu primeiro cliente está à espera.<br><small>Aceite um caso para organizar as diligências e a audiência.</small>'}</div></div>`}<div class="rows" style="margin:18px 0 0 10px"><span class="v5-autos-chip">${active.length} em andamento</span><span class="v5-autos-chip">${played.filter(c=>s.cases[c.id].decision).length} finalizados</span></div></section><section class="v5-balance"><div class="eyebrow">${['SALA NO CENTRO','ESCRITÓRIO CONSOLIDADO','ESCRITÓRIO DE REFERÊNCIA'][s.v5.officeLevel]}</div><strong>${money(s.cash)}</strong><p>Caixa disponível para diligências, perícias e equipe.</p><div class="v5-balance-line"><span>Reputação profissional</span><b>${s.reputation}/100</b></div><button class="btn sm" onclick="nav('escritorio')">Administrar escritório ↗</button></section></div>${s.v5.news.length?newsPage(false):''}</div>`;};
casesPage=function(){let list=CASES.filter(c=>(s.category==='Todas'||c.area===s.category)&&(s.difficulty==='Todas'||c.difficulty===Number(s.difficulty))&&(!s.query||norm(c.title+' '+c.area+' '+c.kind+' '+c.client).includes(norm(s.query))));let pages=Math.max(1,Math.ceil(list.length/12));ui.page=Math.min(ui.page,pages);return `<div class="eyebrow">ARQUIVO DE CAUSAS</div><h1>Uma pasta. Muitas versões.</h1><p class="mini">100 casos independentes · provas rastreáveis · escolhas com consequência.</p><div class="v5-catalog-filter"><input class="search" id="caseSearch" placeholder="Buscar por nome, título ou assunto…" value="${es(s.query)}" oninput="T5.catalogQuery(this.value)"><select class="search" onchange="changeDifficulty(this.value)"><option value="Todas">Todas as dificuldades</option>${[1,2,3,4,5].map(n=>`<option value="${n}" ${String(s.difficulty)===String(n)?'selected':''}>Complexidade ${n}</option>`).join('')}</select></div><div class="casetools">${AREAS.map(a=>`<button class="chip ${s.category===a?'active':''}" onclick="T5.category('${a}')">${a}</button>`).join('')}</div><div class="v5-sectionhead"><span class="v5-toolbar-label">${list.length} pastas encontradas</span><button class="v5-textbtn" onclick="randCase()">Sortear um caso ↗</button></div><div class="v5-foldergrid">${list.slice((ui.page-1)*12,ui.page*12).map(folderCard).join('')}</div>${!list.length?empty('Nenhum caso encontrado.'):''}<div class="v5-pager">${Array.from({length:pages},(_,i)=>`<button class="${ui.page===i+1?'active':''}" onclick="T5.page(${i+1})">${i+1}</button>`).join('')}</div>`;};
let queryTimer;T.catalogQuery=q=>{clearTimeout(queryTimer);queryTimer=setTimeout(()=>{s.query=q;ui.page=1;let pos=$('caseSearch')?.selectionStart;safeRefresh();$('caseSearch')?.focus();$('caseSearch')?.setSelectionRange(pos,pos);},180);};
T.category=a=>{ui.page=1;selectCategory(a);};T.page=n=>{ui.page=n;safeRefresh(true);};
function journalLink(id,label){return `<button class="v4-evidence-link" onclick="openEvidence('${es(id)}')">${es(label||id)}</button>`;}
caseHeader=function(c,p){game(c,p);return previous.caseHeader(c,p).replace('<div class="tabs">','<div class="tabs"><button class="'+(s.tab==='conexoes'?'active':'')+'" onclick="goTab(\'conexoes\')">Quadro de conexões</button><button class="'+(s.tab==='pesquisa'?'active':'')+'" onclick="goTab(\'pesquisa\')">Pesquisar nos autos</button>');};
overview=function(c,p){let html=previous.overview(c,p);return `<div class="v5-dossier-anim">${html}<section class="panel"><div class="eyebrow">UM DETALHE MUDA A LEITURA</div><h2>Construa sua própria linha de raciocínio</h2><p>Abra um registro, grife uma passagem e leve a pista para o caderno. No quadro, associe uma alegação à prova e explique a conclusão.</p><div class="rows"><button class="btn primary" onclick="goTab('conexoes')">Abrir quadro de conexões</button><button class="btn" onclick="goTab('pesquisa')">Pesquisar uma palavra-chave</button><button class="btn" onclick="T5.notes()">Meu caderno</button></div></section></div>`;};

function available(c,p){return c.evidence.filter(e=>p.selected.includes(e.id));}
function markBody(body,highlights){let text=es(body);for(const h of highlights){if(h.text)text=text.split(es(h.text)).join('<mark>'+es(h.text)+'</mark>');}return text;}
window.openEvidence=function(id){let c=iCur(),p=pCur(),e=c?.evidence.find(x=>x.id===id);if(!e)return;if(!p.selected.includes(id)){goTab('provas');return toast('Solicite a obtenção do documento antes de examinar seu conteúdo.');}ui.readerId=id;ui.selection=null;closeModal();const g=game(),notes=g.highlights.filter(x=>x.evidenceId===id);document.body.insertAdjacentHTML('beforeend',`<div class="modalbg" id="docModal"><div class="modal"><div class="rows between"><div><div class="eyebrow">LEITOR DE AUTOS · ${es(id)}</div><h3>${es(e.title)}</h3></div><button class="btn sm" onclick="closeModal()">Fechar ✕</button></div><div class="rows"><button class="btn sm primary" onclick="T5.highlight()">Grifar trecho selecionado</button><button class="btn sm" onclick="T5.pin('${id}')">${g.pins.includes(id)?'✓ Fixado no caderno':'Fixar no caderno'}</button><button class="btn sm" onclick="T5.attachFromReader('${id}')">${p.attached.includes(id)?'Retirar dos autos':'Juntar aos autos'}</button><button class="btn sm" onclick="download(evidencePaper(iCur(),iCur().evidence.find(e=>e.id==='${id}')),'${id}.txt')">Exportar TXT</button></div><p class="mini">Selecione uma frase com o mouse ou use a seleção de texto do celular. O botão de grifar salva exatamente o trecho do registro.</p><article class="v5-readersheet"><span class="v5-docbookmark"></span><div class="v5-dochead"><span class="seal">§</span><div><b>TRIBUNAL · ARQUIVO FICCIONAL</b><br>REGISTRO DO CASO ${es(c.id)}<br>Origem: ${es(e.source)}</div></div><div class="rows between"><span class="smallcaps">${es(e.type)}</span><span class="v5-stamp ${p.attached.includes(id)?'v5-flash':''}">${p.attached.includes(id)?'Juntado aos autos':'Cópia para exame'}</span></div><h3 style="margin-top:20px">${es(e.title)}</h3><div class="v5-docbody" id="readerBody">${markBody(e.body,notes)}</div><div class="v5-docfoot"><b>ALCANCE E LIMITES</b><br>${es(e.caution)}<br><br>Integridade: ${es(e.integrity)}<br>${es(e.id)} · Documento de jogo sem validade judicial.</div></article>${notes.length?`<div class="v5-annotations"><h4 style="margin-top:20px">Grifos desta folha</h4>${notes.map(h=>`<div class="v5-highlight-note">${es(h.text)}<small>${es(h.evidenceId)}</small></div>`).join('')}</div>`:''}</div></div>`);Audio.fx('paper');};
document.addEventListener('selectionchange',()=>{const selection=window.getSelection(),reader=$('readerBody');if(selection&&reader&&selection.rangeCount&&reader.contains(selection.anchorNode)&&reader.contains(selection.focusNode)){let text=selection.toString().trim();if(text)ui.selection={text,evidenceId:ui.readerId};}});
T.highlight=()=>{let c=iCur(),p=pCur(),g=game(),selection=ui.selection,e=c?.evidence.find(e=>e.id===ui.readerId);if(!selection||selection.evidenceId!==e?.id||selection.text.length<3)return toast('Selecione primeiro um trecho dentro da folha.');let text=selection.text;if(text.length>650)return toast('Selecione um trecho de até 650 caracteres para manter a pista objetiva.');if(!e.body.includes(text))return toast('O trecho precisa pertencer ao conteúdo original do registro.');if(g.highlights.some(h=>h.evidenceId===e.id&&h.text===text))return toast('Esse trecho já está grifado.');g.highlights.push({id:'H'+Date.now(),text,evidenceId:e.id,day:s.day});if(!g.pins.includes(e.id))g.pins.push(e.id);store();Audio.fx('stamp');openEvidence(e.id);toast('Grifo salvo no caderno deste caso.');};
T.pin=id=>{const c=iCur(),p=pCur(),g=game();if(!p.selected.includes(id))return;let index=g.pins.indexOf(id);if(index<0)g.pins.push(id);else g.pins.splice(index,1);store();if($('docModal'))openEvidence(id);if(ui.noteOpen)drawNotes();toast(index<0?'Documento fixado no caderno.':'Documento removido dos fixados.');};
T.attachFromReader=id=>{attachEv(id);Audio.fx('stamp');openEvidence(id);};
evidencePage=function(c,p){let g=game(c,p),f=flow(p,c),pending=f.events.filter(x=>x.type==='diligencia'&&!x.done),left=c.evidence.filter(e=>!p.selected.includes(e.id)&&!pending.some(x=>x.evidenceId===e.id));return `<div class="eyebrow">CARTÓRIO DO CASO · FONTES IDENTIFICADAS</div><h2>O detalhe está nos autos.</h2><div class="v5-sectionhead"><span class="v5-toolbar-label">${p.selected.length} obtidos · ${p.attached.length} juntados · ${g.highlights.length} grifos</span><button class="v5-textbtn" onclick="goTab('pesquisa')">Buscar uma palavra nos registros ↗</button></div><div class="v5-docgrid"><section><ul class="v5-evidence-index">${c.evidence.map(e=>`<li class="v5-evidence-item ${p.selected.includes(e.id)?'obtained':'locked'}"><div class="rows between"><small>${es(e.id)} · ${es(e.type)}</small><span class="tag ${p.attached.includes(e.id)?'green':'gold'}">${p.attached.includes(e.id)?'Juntado':p.selected.includes(e.id)?'Disponível':'A obter'}</span></div><h4>${es(e.title)}</h4><small>${es(e.source)}</small>${p.selected.includes(e.id)?`<div class="rows" style="margin-top:11px"><button class="btn sm" onclick="openEvidence('${e.id}')">Examinar folha ↗</button><button class="btn sm" onclick="attachEv('${e.id}')">${p.attached.includes(e.id)?'Retirar juntada':'Juntar aos autos'}</button><button class="btn sm ghost" onclick="T5.pin('${e.id}')">${g.pins.includes(e.id)?'✓ Fixado':'Fixar'}</button></div>`:'<p class="mini">O título identifica o que buscar. O conteúdo só aparece após a diligência.</p>'}</li>`).join('')}</ul></section><aside><section class="panel"><div class="eyebrow">DILIGÊNCIAS</div><h3>Buscar o que falta</h3><p class="mini">Custo, prazo e entrega são registrados no calendário. Melhores equipamentos reduzem custo; a equipe reduz o prazo.</p><div class="field"><label>Documento ou esclarecimento</label><select id="diligenceTarget">${left.map(e=>`<option value="${e.id}">${es(e.title)}</option>`).join('')}</select></div><button class="btn primary" onclick="revealNext()" ${!left.length?'disabled':''}>Solicitar diligência</button>${pending.map(e=>`<p class="v4-context" style="margin-top:13px">${es(c.evidence.find(x=>x.id===e.evidenceId)?.title||e.evidenceId)}<br><small>Entrega no dia ${e.day}</small></p>`).join('')}</section><section class="panel"><h3>Seu método</h3><ol class="mini"><li>Leia a versão e sua fonte.</li><li>Grife o trecho exato.</li><li>Compare período, valor e contexto.</li><li>Explique a conexão que a prova permite.</li></ol><button class="btn sm" onclick="goTab('conexoes')">Ir ao quadro de conexões</button></section></aside></div>`;};
revealNext=function(){let c=iCur(),p=pCur(),f=flow(p,c),occupied=new Set(f.events.filter(e=>e.type==='diligencia'&&!e.done).map(e=>e.evidenceId)),e=c.evidence.find(e=>e.id===$('diligenceTarget')?.value&&!p.selected.includes(e.id)&&!occupied.has(e.id));if(!e)return toast('Selecione uma diligência ainda não solicitada.');const cost=Math.round((e.type==='Laudo'||e.type==='Parecer'?850:350+c.difficulty*100)*(s.v5.upgrades.equipment ? 0.8 : 1)),days=Math.max(2,3+c.difficulty*2+(e.type==='Laudo'?4:0)-(s.v5.upgrades.intern?2:0));if(s.cash<cost)return toast('Caixa insuficiente para '+money(cost)+'.');s.cash-=cost;let due=s.day+days;f.events.push({id:'diligencia-'+Date.now()+'-'+e.id,type:'diligencia',day:due,detail:'Obtenção de '+e.title+' — '+money(cost),evidenceId:e.id,done:false});f.events.sort((a,b)=>a.day-b.day);doc(p,c,'Requisição de diligência — '+e.title,`Documento: ${e.id}\nCustodiante: ${e.source}\nCusto: ${money(cost)}\nEntrega prevista no dia ${due}.\nEscopo: ${e.caution}`,'Diligência');addLog(p,'Diligência '+e.id+' solicitada: '+money(cost)+'; entrega no dia '+due+'.');safeRefresh();toast('Diligência agendada por '+money(cost)+'. Entrega em '+days+' dias.');};

function searchPage(c,p){let q=ui.search,results=q.length>=2?available(c,p).filter(e=>norm(e.body+' '+e.title).includes(norm(q))):[];return `<section class="panel"><div class="eyebrow">PESQUISA CRUZADA</div><h2>Encontre a palavra que conecta.</h2><p class="mini">A pesquisa percorre somente documentos obtidos neste processo, sem antecipar conteúdo bloqueado.</p><div class="rows"><input class="search" id="autosSearch" style="flex:1" value="${es(q)}" placeholder="Ex.: 20h04, reembolso, senha, assinatura…" onkeydown="if(event.key==='Enter')T5.searchAutos()"><button class="btn primary" onclick="T5.searchAutos()">Pesquisar nos autos</button></div>${q.length<2?empty('Digite pelo menos dois caracteres.'):results.length?`<p class="mini" style="margin-top:16px">${results.length} registros contêm o termo.</p>${results.map(e=>{let pos=norm(e.body).indexOf(norm(q));let snippet=e.body.slice(Math.max(0,pos-65),Math.max(0,pos-65)+250);return `<button class="v5-searchresult" onclick="openEvidence('${e.id}')"><span class="v5-case-id">${es(e.id)}</span><h4>${es(e.title)}</h4><p>${es(snippet)}</p></button>`;}).join('')}`:empty('Nenhuma ocorrência nos documentos já obtidos.')}</section>`;}
T.searchAutos=()=>{ui.search=$('autosSearch')?.value.trim()||'';safeRefresh();};
T.notes=()=>{if(!pCur())return toast('Abra um caso para usar o caderno.');ui.noteOpen=!ui.noteOpen;drawNotes();};
function drawNotes(){document.querySelector('.v5-note-drawer')?.remove();if(!ui.noteOpen||!pCur())return;let c=iCur(),p=pCur(),g=game();document.body.insertAdjacentHTML('beforeend',`<aside class="v5-note-drawer" aria-label="Caderno do caso"><div class="rows between"><div><div class="eyebrow">CADERNO DO ADVOGADO</div><h3>${es(c.id)}</h3></div><button class="btn sm" onclick="T5.notes()">Fechar ✕</button></div><p class="mini">Suas notas são privadas do escritório; não são prova nem vão automaticamente à ata.</p><textarea id="v5Notes" placeholder="Hipóteses, perguntas, pontos que ainda faltam…" oninput="T5.saveNotes(this.value)">${es(g.notes)}</textarea><h4 style="margin-top:22px">Documentos fixados</h4>${g.pins.map(id=>journalLink(id,c.evidence.find(e=>e.id===id)?.title||id)).join('')||'<p class="mini">Abra uma folha e escolha Fixar.</p>'}<h4 style="margin-top:22px">Passagens grifadas</h4>${g.highlights.map(h=>`<div class="v5-highlight-note">${es(h.text)}<small>${es(h.evidenceId)}</small><button class="v5-textbtn" onclick="openEvidence('${h.evidenceId}')">Abrir origem</button></div>`).join('')||'<p class="mini">Selecione um trecho de uma folha para grifar.</p>'}</aside>`);}
T.saveNotes=value=>{game().notes=value;clearTimeout(saveTimer);saveTimer=setTimeout(store,350);};

function boardEvidence(c,p,g){let chosen=g.boardEvidence||[],ids=[...new Set([...chosen,...g.pins,...c.evidence.slice(2,7).map(e=>e.id)])];return ids.map(id=>c.evidence.find(e=>e.id===id)).filter(e=>e&&p.selected.includes(e.id)).slice(0,5);}
function boardPage(c,p){const g=game(c,p),facts=c.deductions||[],proofs=boardEvidence(c,p,g),mobile=innerWidth<700;let pin=(item,type,i)=>{let key=type+'-'+item.id,pos=g.positions[(mobile?'m:':'d:')+key],defaultX=type==='fact'?16:Math.max(290,innerWidth<1040?innerWidth-355:innerWidth-610),defaultY=25+i*155;if(mobile){defaultX=5;defaultY=20+(type==='fact'?i:i+facts.length)*124;}return `<button class="v5-pin ${type==='proof'?'evidencepin':''} ${ui.boardFact===item.id?'selected':''}" data-node="${es(key)}" data-type="${type}" data-id="${es(item.id)}" style="left:${pos?.x??defaultX}px;top:${pos?.y??defaultY}px" onclick="T5.boardClick('${type}','${es(item.id)}')"><small>${type==='fact'?'ALEGAÇÃO / HIPÓTESE':'DOCUMENTO OBTIDO'} · ${es(item.id)}</small><strong>${es(short(type==='fact'?item.fact:item.title,140))}</strong>${type==='proof'?'<small>'+es(short(item.body,75))+'</small>':'<small>Clique para iniciar a conexão</small>'}</button>`;};return `<div class="eyebrow">MESA DE INVESTIGAÇÃO</div><h2>Entre uma versão e a prova.</h2><p class="mini">Escolha uma alegação, clique na prova e escreva a conclusão. Arraste as fichas para organizar o quadro. Uma hipótese pode ficar registrada sem ser tratada como fato provado.</p><div class="rows" style="margin-bottom:14px"><select id="boardProofPick" class="search" style="max-width:420px">${available(c,p).map(e=>`<option value="${e.id}">${es(e.title)}</option>`).join('')}</select><button class="btn sm" onclick="T5.boardAddProof()">Levar prova ao quadro</button><button class="btn sm" onclick="T5.resetBoard()">Organizar fichas</button></div><div class="v5-board"><div class="v5-board-stage" id="boardStage" style="${mobile?'height:'+Math.max(1040,(facts.length+proofs.length)*124+30)+'px':''}"><svg class="v5-board-wires" id="boardWires" aria-hidden="true"></svg>${facts.map((x,i)=>pin(x,'fact',i)).join('')}${proofs.map((x,i)=>pin(x,'proof',i)).join('')}</div></div><section class="panel" style="margin-top:20px"><div class="rows between"><h3>Seu raciocínio em três passos</h3><span class="tag">${g.connections.filter(x=>x.valid).length} conexões sustentadas</span></div>${g.connections.map(x=>`<div class="v5-chain"><div><b>Alegação</b>${es(short(facts.find(f=>f.id===x.factId)?.fact,150))}</div><span class="arrow">→</span><div><b>Prova</b>${journalLink(x.evidenceId)}<small>${es(x.relation)}</small></div><span class="arrow">→</span><div><b>Conclusão · ${x.valid?'sustentada':'hipótese'}</b>${es(x.conclusion)}<br><button class="v5-textbtn" onclick="T5.removeConnection('${x.id}')">Remover</button></div></div>`).join('')||empty('As conexões que você construir aparecerão aqui.')}</section>`;}
T.boardAddProof=()=>{const id=$('boardProofPick')?.value,g=game();g.boardEvidence=[id,...(g.boardEvidence||[]).filter(x=>x!==id)];safeRefresh();};
T.resetBoard=()=>{game().positions={};safeRefresh();};
T.boardClick=(type,id)=>{if(ui.drawing)return;if(type==='fact'){ui.boardFact=id;document.querySelectorAll('[data-type="fact"]').forEach(x=>x.classList.toggle('selected',x.dataset.id===id));toast('Agora escolha a prova que você quer relacionar.');return;}if(!ui.boardFact)return toast('Escolha primeiro uma alegação do quadro.');openConnection(ui.boardFact,id);};
function openConnection(fid,eid){const c=iCur(),p=pCur(),f=c.deductions.find(x=>x.id===fid),e=c.evidence.find(x=>x.id===eid);if(!f||!e||!p.selected.includes(eid))return;closeModal();document.body.insertAdjacentHTML('beforeend',`<div class="modalbg" id="docModal"><div class="modal"><div class="rows between"><h3>Da pista à conclusão</h3><button class="btn sm" onclick="closeModal()">Fechar ✕</button></div><p class="v4-context"><b>Alegação:</b> ${es(f.fact)}</p><p><b>Prova:</b> ${es(e.title)} · ${es(eid)}</p><div class="paper">${es(e.body)}</div><div class="field"><label>O que a prova faz em relação à alegação?</label><select id="connectionRelation"><option value="limita">Limita o que se pode concluir</option><option value="contextualiza">Acrescenta contexto relevante</option><option value="contradiz">Contradiz a afirmação</option><option value="corrobora">Corrobora a afirmação</option></select></div><div class="field"><label>Explique com suas palavras, apontando o trecho, valor ou horário</label><textarea id="connectionConclusion" placeholder="O registro mostra…, por isso a afirmação permite concluir apenas…"></textarea></div><button class="btn primary" onclick="T5.connect('${fid}','${eid}')">Registrar conexão</button></div></div>`);}
T.connect=(fid,eid)=>{const c=iCur(),p=pCur(),g=game(),fact=c.deductions.find(x=>x.id===fid),text=$('connectionConclusion')?.value.trim()||'',relation=$('connectionRelation')?.value;if(text.length<35)return toast('Desenvolva uma conclusão com pelo menos 35 caracteres.');let key=fid+'|'+eid+'|'+relation;if(g.connections.some(x=>x.key===key))return toast('Essa conexão já está registrada.');const valid=fact.validEvidence.includes(eid)&&fact.relation===relation;g.connections.push({id:'C'+Date.now(),key,factId:fid,evidenceId:eid,conclusion:text,relation,valid,day:s.day});if(valid&&!g.confrontKeys.includes('board-'+fid)){g.credibility=Math.min(100,g.credibility+3);g.confrontKeys.push('board-'+fid);}if(!valid)g.credibility=Math.max(0,g.credibility-2);g.drafts.connectionConclusion='';addLog(p,'Conexão '+(valid?'sustentada':'registrada como hipótese')+': '+fid+' / '+eid);closeModal();Audio.fx(valid?'stamp':'paper');safeRefresh();toast(valid?'Conexão sustentada pelos registros. Leve-a às alegações finais.':'Hipótese registrada. A fonte ou relação escolhida não sustenta esta leitura; revise os limites do documento.');};
T.removeConnection=id=>{game().connections=game().connections.filter(x=>x.id!==id);safeRefresh();};
function drawBoard(){let stage=$('boardStage'),svg=$('boardWires');if(!stage||!svg)return;let r=stage.getBoundingClientRect(),g=game();svg.innerHTML=g.connections.map(x=>{let a=stage.querySelector('[data-node="fact-'+x.factId+'"]'),b=stage.querySelector('[data-node="proof-'+x.evidenceId+'"]');if(!a||!b)return '';let ar=a.getBoundingClientRect(),br=b.getBoundingClientRect();return `<line x1="${ar.left-r.left+ar.width/2}" y1="${ar.top-r.top+10}" x2="${br.left-r.left+br.width/2}" y2="${br.top-r.top+10}" stroke="${x.valid?'#ac483a':'#c7b98b'}" stroke-width="2.5" ${x.valid?'':'stroke-dasharray="5 4"'}/>`;}).join('');}
let drag;
document.addEventListener('pointerdown',e=>{const node=e.target.closest('.v5-pin'),stage=$('boardStage');if(!node||!stage)return;drag={node,x:e.clientX,y:e.clientY,left:parseFloat(node.style.left),top:parseFloat(node.style.top),moved:false};node.setPointerCapture(e.pointerId);});
document.addEventListener('pointermove',e=>{if(!drag)return;let dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.abs(dx)+Math.abs(dy)>5)drag.moved=true;if(!drag.moved)return;e.preventDefault();ui.drawing=true;const stage=$('boardStage'),x=Math.max(0,Math.min(stage.clientWidth-drag.node.offsetWidth,drag.left+dx)),y=Math.max(0,Math.min(stage.clientHeight-drag.node.offsetHeight,drag.top+dy));drag.node.style.left=x+'px';drag.node.style.top=y+'px';game().positions[(innerWidth<700?'m:':'d:')+drag.node.dataset.node]={x,y};drawBoard();});
document.addEventListener('pointerup',()=>{if(!drag)return;drag=null;store();setTimeout(()=>ui.drawing=false,100);});

function shortAnswer(c,w,q,p,eid){if(window.TribunalDialogue)return TribunalDialogue.answer(c,w,q,p,eid);const k=norm(q),known=w.answers||[];let e=c.evidence.find(e=>e.id===(eid||c.evidence.find(e=>k.includes(norm(e.id)))?.id));
 if(!e&&/sua renda|seu salario|voce recebe|voce ganha|quanto ganha/.test(k))return {text:w.profile.income==null?'Minha renda pessoal não foi apurada neste processo. Posso responder sobre meu vínculo e os registros que conheço.':`O valor registrado para mim é ${money(w.profile.income)}. ${w.profile.incomeStatus}`,source:null};
 if(!e&&/lucro|reembolso|renda|financeir|pensao/.test(k)&&c.financial){if(w===c.witnesses[2])return {text:w.statement+' Não acesso a renda privada dos responsáveis.',source:null};e=c.evidence.find(e=>e.id===c.financial.incomeEvidence[0]);}
 if(!e){const scored=c.evidence.filter(e=>p.selected.includes(e.id)&&known.some(a=>a.evidenceId===e.id)).map(e=>({e,score:norm(e.title).split(/\W+/).filter(t=>t.length>4&&k.includes(t)).length})).sort((a,b)=>b.score-a.score);if(scored[0]?.score>=2)e=scored[0].e;}
 if(e){if(!p.selected.includes(e.id))return {text:'Esse documento ainda não foi obtido. Não vou antecipar um conteúdo que precisa ser requisitado.',source:null};if(!known.some(a=>a.evidenceId===e.id))return {text:'Não produzi esse registro e não tenho conhecimento direto para atestá-lo. '+short(w.statement,260),source:e.id};const content=e.body.split(/(?<=[.!?])\s+(?=[A-ZÁÉÍÓÚ])/).slice(0,3).join(' ');return {text:short(content,530),source:e.id,full:e.body};}
 if(/interesse|relacao|profiss|quem e/.test(k))return {text:`${w.profile.occupation}. ${short(w.profile.background,360)} Meu interesse é ${w.interest.toLowerCase()}.`,source:null};
 if(/limite|certeza|nao sabe|terceir/.test(k))return {text:short(w.statement,340)+' '+w.profile.limit,source:null};
 if(/contradi|diverg|omiti/.test(k))return {text:short(w.statement,330)+' Indique o registro específico para que eu explique o ponto dentro do que conheço.',source:null};
 return {text:short(w.statement,490),source:null};
}
function chosen(c,p){return c.witnesses.find(w=>w.id===p.chosenPerson)||c.witnesses[0];}
T.person=id=>{pCur().chosenPerson=id;safeRefresh();};
function mood(g,w){return g.moods[w.id]||(w.interest==='Direto'?'Reticente':'Colaborativo');}
function interviewStage(c,p,formal){let g=game(c,p),w=chosen(c,p),last=g.lastAnswer?.who===w.name?g.lastAnswer:null,documents=available(c,p).filter(e=>w.answers.some(a=>a.evidenceId===e.id));return `<div class="v5-courtstage"><div class="v5-mug"><img src="${w.portrait}" alt="Retrato noir de ${es(w.name)}"><span class="v5-stamp">${formal?'Em audiência':'Entrevista'}</span></div><div class="v5-who"><span class="v5-case-id">${es(w.role)}</span><h3>${es(w.name)}</h3><details class="v5-participation"><summary>Contexto da participação</summary><p>${es(w.profile.background)}</p><p>${es(w.profile.limit)}</p></details><span class="v5-mood">POSTURA NARRATIVA: ${es(mood(g,w))}</span>${last?.question?`<p class="v5-answer-question"><b>Pergunta:</b> ${es(last.question)}</p>`:''}<div class="v5-dialogue" id="v5Dialogue" data-answer="${last?.id||'initial'}">${es(last?.text||w.statement)}</div><div class="rows"><span class="mini">${last?.sources?.length?last.sources.map(id=>journalLink(id,'Fonte · '+id)).join(''):last?.source?journalLink(last.source,'Examinar fonte da resposta'):'Conhecimento delimitado ao relato desta pessoa.'}</span><button class="v5-fast-forward" onclick="T5.skipText()">Mostrar texto completo ↗</button></div></div><div class="v5-question-buttons"><div class="field"><label>Pessoa a ouvir</label><select id="${formal?'oralPerson':'personSel'}" onchange="T5.person(this.value)">${c.witnesses.map(x=>`<option value="${x.id}" ${x.id===w.id?'selected':''}>${es(x.name)} — ${es(x.role)}</option>`).join('')}</select></div><div class="field"><label>Documento para uma pergunta específica</label><select id="questionEvidence"><option value="">Falar sobre o relato e sua percepção</option>${documents.map(e=>`<option value="${e.id}">${es(e.title)}</option>`).join('')}</select></div><div class="rows"><button class="btn sm" onclick="T5.quickQuestion('fato',${formal})">O que você presenciou?</button><button class="btn sm" onclick="T5.quickQuestion('documento',${formal})">Explique o registro escolhido</button><button class="btn sm" onclick="T5.quickQuestion('limite',${formal})">Qual é o limite do seu relato?</button><button class="btn sm" onclick="T5.quickQuestion('origem',${formal})">Como você sabe disso?</button><button class="btn sm" onclick="T5.quickQuestion('cronologia',${formal})">Explique a sequência dos fatos</button><button class="btn sm" onclick="T5.quickQuestion('divergencia',${formal})">Explique essa divergência</button></div><div class="field" style="margin-top:9px"><label>Pergunta complementar</label><textarea id="${formal?'oralQuestion':'ask'}" placeholder="Pergunte sem induzir a resposta. Você pode citar um ID de prova."></textarea></div><button class="btn primary" onclick="T5.ask(${formal})">${formal?'Perguntar e registrar na ata':'Registrar entrevista preparatória'}</button><p class="v5-legalnotice">A postura é uma reação narrativa do jogo e não indica verdade ou mentira. A leitura não consome atenção. ${formal?'Perguntas podem ser indeferidas se forem indutivas, estranhas à causa ou repetitivas.':''}</p></div></div>`;}
interviewsPage=function(c,p){return `<div class="eyebrow">ANTES DA AUDIÊNCIA</div><h2>Ouça antes de concluir.</h2>${interviewStage(c,p,false)}<details class="panel"><summary>Consultar entrevistas anteriores (${p.messages.filter(x=>x.role==='npc').length})</summary><div class="chatlog" id="chatlog">${p.messages.map(m=>`<div class="bubble ${m.role==='player'?'mine':''}"><b>${es(m.who)}</b><br>${es(m.text)}</div>`).join('')||empty('Nenhuma entrevista registrada.')}</div></details>`;};
T.quickQuestion=(kind,formal)=>{const e=$('questionEvidence')?.value,c=iCur();let q=kind==='origem'?'Como você sabe disso? O que presenciou e o que veio de um registro?':kind==='cronologia'?'Qual a sequência dos fatos e o que aconteceu antes e depois?':kind==='divergencia'?'Como você explica a divergência nesse ponto? O que muda quando os registros são confrontados?':kind==='fato'?'O que você presenciou diretamente e o que soube por terceiros?':kind==='limite'?'Qual é o limite do que você sabe com certeza neste caso?':e?'Explique o que o registro '+e+' permite afirmar e o que ele não prova.':'Qual ponto do seu relato pode ser confrontado com um documento?';askQuestion(q,formal,['documento','origem','cronologia','divergencia'].includes(kind)?e:null);};
T.ask=formal=>{const q=$(formal?'oralQuestion':'ask')?.value.trim();if(!q)return toast('Escreva sua pergunta.');askQuestion(q,formal,$('questionEvidence')?.value||null);};
chat=async()=>T.ask(false);window.askOral=()=>T.ask(true);
window.askSuggested=(i,formal=false)=>{const c=iCur(),p=pCur(),w=chosen(c,p),all=[{q:'O que você presenciou diretamente?',id:null},{q:'Qual é sua relação com as partes?',id:null},...w.answers.filter(a=>p.selected.includes(a.evidenceId)).map(a=>({q:a.question,id:a.evidenceId}))];if(all[i])askQuestion(all[i].q,formal,all[i].id);};
function askQuestion(q,formal,eid){const c=iCur(),p=pCur(),g=game(),w=chosen(c,p);if(formal&&!flow(p,c).hearingOpened)return toast('A audiência precisa estar aberta para produzir depoimento.');
 const bad=/idiota|mentiroso|confesse|admita que|nao e verdade que|voce matou|voce roubou/.test(norm(q));const key=w.id+'|'+norm(q)+'|'+(eid||g.dialogueFocus?.[w.id]?.source||''),repeat=g.questionKeys.includes(key);
 if(formal&&bad){g.credibility=Math.max(0,g.credibility-5);g.attention=Math.max(0,g.attention-4);g.moods[w.id]='Defensivo';p.transcript.push({who:s.lawyer,text:q},{who:c.area==='Penal'?'Acusação':'Parte adversa',text:'Protesto contra formulação indutiva ou ofensiva.'},{who:'Juízo',text:'Pergunta indeferida nesta forma. Reformule de modo pertinente e respeitoso, sem sugerir a resposta.'});addLog(p,'Pergunta indeferida por formulação inadequada; nenhum fato novo foi produzido.');safeRefresh();return toast('Reformule a pergunta. A premissa sugerida não se transforma em prova.');}
 if(formal&&repeat){g.attention=Math.max(0,g.attention-2);p.transcript.push({who:'Juízo',text:'O ponto já foi respondido; esclareça uma divergência específica para evitar repetição.'});safeRefresh();return toast('Pergunta já respondida. Avance para outro ponto ou documento.');}
 let answer=shortAnswer(c,w,q,p,eid);p.witnessQuestionCount++;g.questionKeys.push(key);g.lastAnswer={id:'A'+Date.now(),who:w.name,text:answer.text,source:answer.source,full:answer.full,formal,question:q,topic:answer.topic,sources:answer.sources||[answer.source].filter(Boolean)};g.moods[w.id]='Colaborativo';const questionField=$(formal?'oralQuestion':'ask');if(questionField?.value.trim()===q){questionField.value='';g.drafts[formal?'oralQuestion':'ask']='';}
 if(formal){p.transcript.push({who:s.lawyer,text:'Pergunta a '+w.name+': '+q},{who:w.name+' ('+w.role+')',text:answer.text});if(!p.oral.heard.includes(w.id))p.oral.heard.push(w.id);p.oral.answers.push({witnessId:w.id,question:q,answer:answer.text,evidenceId:answer.source||'',day:s.day});if(answer.source&&!p.oral.confronted.includes(answer.source))p.oral.confronted.push(answer.source);if(!p.hearingActions.includes('depoimento'))p.hearingActions.push('depoimento');g.attention=Math.max(0,g.attention-1);if(answer.source)g.credibility=Math.min(100,g.credibility+1);}
 else{p.messages.push({role:'player',who:s.lawyer,text:q,to:w.name,day:s.day},{role:'npc',who:w.name,text:answer.text,day:s.day});doc(p,c,'Entrevista preparatória — '+w.name,`${s.lawyer}: ${q}\n\n${w.name}: ${answer.text}\nFonte: ${answer.source||'relato'}`,'Entrevista');}
 addLog(p,(formal?'Depoimento judicial':'Entrevista preparatória')+' de '+w.name);Audio.fx('type');safeRefresh();
}
let typing=null;T.skipText=()=>{if(typing){clearInterval(typing.timer);typing.el.textContent=typing.full;typing=null;}};
function animateDialogue(){const el=$('v5Dialogue');if(!el||el.dataset.answer==='initial'||ui.lastTyped===el.dataset.answer||matchMedia('(prefers-reduced-motion: reduce)').matches)return;T.skipText();ui.lastTyped=el.dataset.answer;const full=el.textContent;let i=0;el.textContent='';typing={el,full,timer:setInterval(()=>{if(!el.isConnected){T.skipText();return;}i+=15;el.textContent=full.slice(0,i);if(i%90===0)Audio.fx('type');if(i>=full.length)T.skipText();},18)};}
function metrics(c,p){let g=game(c,p);return `<div class="v5-metrics"><div class="v5-metric"><label><span>Consistência da atuação</span><span>${g.credibility}/100</span></label><div class="v5-meter"><i style="width:${g.credibility}%"></i></div></div><div class="v5-metric"><label><span>Atenção na audiência</span><span>${g.attention}/100</span></label><div class="v5-meter"><i style="width:${g.attention}%"></i></div></div><div class="v5-metricsmall">Protestos no desafio<strong>${g.objections} restantes</strong></div></div><p class="v5-legalnotice">Indicadores de gameplay. Não medem culpa, verdade, credibilidade real de pessoas ou probabilidade judicial. Os protestos fora do desafio continuam livres.</p>`;}
function confrontPanel(c,p){let docs=c.evidence.filter(e=>p.attached.includes(e.id)&&p.selected.includes(e.id));return `<section class="panel"><div class="eyebrow">CONFRONTO PROBATÓRIO</div><h3>Uma afirmação. Uma prova.</h3><div class="field"><label>Alegação ou leitura que você quer confrontar</label><select id="confrontFact">${c.deductions.map(f=>`<option value="${f.id}">${es(short(f.fact,170))}</option>`).join('')}</select></div><div class="field"><label>Prova já juntada</label><select id="confrontEvidence">${docs.map(e=>`<option value="${e.id}">${es(e.title)}</option>`).join('')}</select></div><div class="field"><label>Explique o confronto</label><textarea id="confrontReason" placeholder="A afirmação deve ser lida com este limite porque o documento registra…"></textarea></div><button class="btn primary" onclick="T5.confront()" ${!docs.length?'disabled':''}>Apresentar confronto ao juízo</button><p class="mini">Confrontar é demonstrar a relação entre conteúdo e alegação. O título de um documento não basta.</p></section>`;}
T.confront=()=>{const c=iCur(),p=pCur(),g=game(),f=c.deductions.find(x=>x.id===$('confrontFact')?.value),e=c.evidence.find(x=>x.id===$('confrontEvidence')?.value),reason=$('confrontReason')?.value.trim()||'';if(!flow(p,c).hearingOpened)return toast('Abra a audiência primeiro.');if(!f||!e||!p.attached.includes(e.id)||reason.length<40)return toast('Escolha alegação, prova juntada e explique a relação (40 caracteres).');const key='court-'+f.id+'-'+e.id;if(g.confrontKeys.includes(key))return toast('Este confronto já foi apreciado.');g.confrontKeys.push(key);const valid=f.validEvidence.includes(e.id);g.credibility=Math.max(0,Math.min(100,g.credibility+(valid?5:-7)));g.attention=Math.max(0,Math.min(100,g.attention+(valid?3:-5)));p.transcript.push({who:s.lawyer,text:`Confronto: ${f.fact}\nProva: ${e.id}. ${reason}`},{who:'Juízo',text:valid?'A relação com o ponto controvertido fica consignada, respeitados os limites do registro: '+f.conclusion:'A fonte apresentada não enfrenta diretamente esse ponto. A alegação permanece dependente de suporte pertinente.'});if(valid&&!p.oral.confronted.includes(e.id))p.oral.confronted.push(e.id);addLog(p,'Confronto '+(valid?'pertinente':'sem relação demonstrada')+' entre '+f.id+' e '+e.id);Audio.fx('stamp');safeRefresh();toast(valid?'Confronto pertinente registrado na ata.':'O documento não enfrenta essa alegação; revise a conexão.');};

function opponentPanel(c,p){const g=game(c,p),challenge=ui.challenge?.caseId===c.id?ui.challenge:null;return `<section class="panel"><div class="eyebrow">A OUTRA PARTE TAMBÉM PERGUNTA</div><h3>Escute. Avalie. Intervenha.</h3>${challenge?`<div class="v5-opponent"><h4>${c.area==='Penal'?'Acusação':'Parte adversa'}</h4><p>${es(challenge.question)}</p><span class="v5-countdown" id="challengeClock">${challenge.remaining==null?'Sem cronômetro — decida no seu ritmo.':challenge.remaining+' segundos'}</span></div><div class="rows">${[['inducao','Protestar: pergunta indutiva'],['pertinencia','Protestar: estranha à causa'],['repeticao','Protestar: já respondida'],['seguir','Permitir a pergunta']].map(([id,label])=>`<button class="btn sm" onclick="T5.resolveChallenge('${id}')">${label}</button>`).join('')}</div>`:`<p class="mini">A próxima intervenção pode exigir protesto ou ser uma pergunta legítima. Não há penalidade por ler antes de iniciar.</p><button class="btn" onclick="T5.opponentTurn()" ${g.challengeIndex>=3?'disabled':''}>${g.challengeIndex>=3?'Intervenções deste ciclo concluídas':'Ouvir intervenção adversa'}</button>`}<p class="v5-legalnotice">Fundamentos didáticos: perguntas indutivas, sem pertinência ou repetitivas podem ser indeferidas. Consulte <a href="https://www.planalto.gov.br/ccivil_03/decreto-lei/del3689compilado.htm" target="_blank" rel="noopener">CPP, art. 212</a> e <a href="https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2015/lei/l13105.htm" target="_blank" rel="noopener">CPC, art. 459</a>. A quantidade de protestos é apenas recurso do minijogo.</p></section>`;}
T.opponentTurn=()=>{let c=iCur(),p=pCur(),g=game();if(!flow(p,c).hearingOpened||g.challengeIndex>=3)return;const e=c.evidence.find(e=>p.attached.includes(e.id))||c.evidence[2];const previousQuestion=p.oral.answers.find(a=>a.question);const turns=[{question:`Você confirma sem ressalvas a seguinte conclusão sobre ${c.client}: ${short(c.opponentClaim,170)} Correto?`,correct:'inducao',reason:'A formulação sugere a conclusão e induz a resposta; o correto é formular pergunta aberta sobre o fato.'},previousQuestion?{question:previousQuestion.question,correct:'repeticao',reason:'Esta pergunta já consta respondida na ata. Sem delimitar dúvida nova, a repetição pode ser indeferida.'}:{question:`Sem relação demonstrada com ${c.kind.toLowerCase()}: qual o time esportivo de uma pessoa estranha a estes fatos?`,correct:'pertinencia',reason:'A pergunta introduz informação estranha ao ponto controvertido e sem relação demonstrada com a causa.'},{question:`O que o registro ${e.id}, ${e.title.toLowerCase()}, permite afirmar dentro do período que documenta?`,correct:'seguir',reason:'A pergunta é aberta, pertinente ao documento e não sugere uma conclusão.'}];ui.challenge={...turns[g.challengeIndex],caseId:c.id,remaining:s.v5.timed?25:null};safeRefresh();if(s.v5.timed)startClock();};
function stopClock(){clearInterval(ui.timer);ui.timer=null;}
function startClock(){stopClock();ui.timer=setInterval(()=>{let ch=ui.challenge;if(!ch||ch.remaining==null){stopClock();return;}if(document.hidden||$('docModal')||ui.noteOpen||(s.tab!=='audiencia'&&!(s.tab==='mesa6'&&window.T6?.isHearingPane())))return;ch.remaining--;let el=$('challengeClock');if(el)el.textContent=ch.remaining+' segundos';if(ch.remaining<=0)T.resolveChallenge('seguir',true);},1000);}
T.resolveChallenge=(choice,expired=false)=>{const c=iCur(),p=pCur(),g=game(),ch=ui.challenge;if(!ch||ch.caseId!==c.id)return;const protesting=choice!=='seguir';if(protesting&&g.objections<=0)return toast('Os recursos deste minijogo acabaram. Você pode permitir a pergunta e registrar requerimentos livres na ata.');if(protesting)g.objections--;const correct=choice===ch.correct;g.credibility=Math.max(0,Math.min(100,g.credibility+(correct?3:protesting?-5:-2)));g.attention=Math.max(0,Math.min(100,g.attention+(correct?2:-3)));g.challengeHistory.push({question:ch.question,choice,correct,day:s.day});g.challengeIndex++;p.transcript.push({who:c.area==='Penal'?'Acusação':'Parte adversa',text:ch.question},{who:s.lawyer,text:protesting?'Protesto pela formulação: '+choice+'.':'Sem protesto quanto à pergunta.'},{who:'Juízo',text:correct?ch.correct==='seguir'?'Pergunta admitida, respeitados os limites do conhecimento da pessoa.':'Protesto acolhido neste ponto; reformule a pergunta. '+ch.reason:'Intervenção apreciada: '+ch.reason});ui.challenge=null;stopClock();Audio.fx('stamp');safeRefresh();toast((expired?'Tempo encerrado. ':'')+(correct?'Leitura processual adequada. ':'Revise o fundamento. ')+ch.reason);};
startHearing=function(){previous.startHearing();if(pCur()?.workflow?.hearingOpened){let g=game(),cycle=(flow(pCur(),iCur()).plenary?'plenario':'audiencia')+'-'+s.day;if(g.cycle!==cycle){g.cycle=cycle;g.closing=null;g.challengeIndex=0;g.objections=3+(s.v5.upgrades.library?1:0);g.questionKeys=[];g.confrontKeys=g.confrontKeys.filter(x=>x.startsWith('board-'));}if(g.ethicalChoice==='candid'&&g.consulted&&iCur().ethics?.privateAdmission&&g.admissionCycle!==cycle){g.admissionDisclosed=true;g.admissionCycle=cycle;pCur().transcript.push({who:s.lawyer,text:'Reconhecimento delimitado e autorizado no roteiro: '+iCur().ethics.privateAdmission});}Audio.fx('gavel');safeRefresh();}};
hearingPage=function(c,p){const f=flow(p,c),g=game(c,p);if(!f.hearingOpened)return previous.hearingPage(c,p);return `<div class="eyebrow">SALA DE AUDIÊNCIA · ${es(c.area)}</div><h2>O que os autos permitem afirmar?</h2>${metrics(c,p)}${interviewStage(c,p,true)}<div class="v4-grid">${confrontPanel(c,p)}${opponentPanel(c,p)}</div><section class="panel"><div class="rows between"><h3>Ata em construção</h3><span class="tag">${p.oral.heard.length} pessoas ouvidas</span></div><div class="transcript">${p.transcript.map(x=>`<div class="logentry"><b>${es(x.who)}</b><br>${es(x.text)}</div>`).join('')}</div><div class="field" style="margin-top:18px"><label>Requerimento livre ao juízo</label><textarea id="courtSpeech" placeholder="Indique a questão, o documento e a providência que requer."></textarea></div><div class="rows"><button class="btn" onclick="speakAtHearing()">Registrar requerimento</button><button class="btn primary" onclick="goTab('alegacoes')">Construir alegações finais ↗</button></div></section>`;};

function thesisChoices(c){return c.area==='Penal'?[['autoria','Autoria não individualizada'],['duvida','Insuficiência ou dúvida probatória'],['elemento','Elemento subjetivo não demonstrado'],['nexo','Nexo causal ou contexto da conduta'],['legalidade','Legalidade e alcance da prova']]:c.area==='Família'?[['proporcao','Necessidades, capacidade e proporcionalidade'],['interesse','Proteção dos vínculos e interesse da criança'],['patrimonio','Origem de recursos e extensão patrimonial'],['vinculo','Vínculo familiar e requisitos do pedido'],['prova','Pedido limitado ao que está comprovado']]:[['cumprimento','Cumprimento, falha e extensão da obrigação'],['nexo','Nexo causal e danos demonstrados'],['contrato','Contrato, requisitos e limites do pedido'],['procedimento','Regularidade do procedimento e motivação'],['prova','Ônus e suficiência da prova']];}
function closingPage(c,p){const g=game(c,p),f=flow(p,c),docs=available(c,p).filter(e=>p.attached.includes(e.id)),closing=g.closing;return `<div class="eyebrow">A CONSTRUÇÃO DA SUA TESE</div><h2>Três provas. Um raciocínio.</h2><p class="mini">Escolha a tese e até três registros centrais. Explique o que cada um demonstra, incluindo seus limites. A conclusão será registrada antes de remeter os autos à decisão.</p><section class="v5-closing"><div class="field"><label>Tese principal</label><select id="closingThesis">${thesisChoices(c).map(([id,title])=>`<option value="${id}" ${closing?.thesis===id?'selected':''}>${title}</option>`).join('')}</select></div><h4 style="margin:20px 0 13px">Provas centrais já juntadas</h4><div class="evidence-choices">${docs.map(e=>`<label class="v5-check"><input name="closingProof" type="checkbox" value="${e.id}" ${closing?.evidenceIds.includes(e.id)?'checked':''} onchange="T5.limitClosing(this)"><span><b>${es(e.id)}</b><br>${es(e.title)}</span></label>`).join('')||empty('Junte os registros que pretende usar antes de construir a tese.')}</div><div class="field" style="margin-top:22px"><label>Fundamentação final</label><textarea id="closingArgument" style="min-height:170px" placeholder="A tese se sustenta porque… O primeiro registro demonstra… O segundo limita… Requeiro…">${es(closing?.argument||'')}</textarea></div><div class="rows"><button class="btn" onclick="T5.saveClosing()" ${!f.hearingOpened?'disabled':''}>Registrar alegações finais</button><button class="btn primary" onclick="closeInstruction()" ${!f.hearingOpened?'disabled':''}>Encerrar instrução e remeter à decisão</button></div>${closing?.signed?'<p class="success">Alegações registradas. Você pode revê-las enquanto a instrução estiver aberta.</p>':''}<p class="v5-legalnotice">Escolher “legalidade da prova” não exclui um registro automaticamente. A decisão distingue irregularidade alegada, demonstração concreta e consequência juridicamente cabível.</p></section><section class="panel" style="margin-top:20px"><h3>Antes de concluir, decida sua postura</h3>${ethicalPanel(c,p)}</section>`;}
T.limitClosing=el=>{if(document.querySelectorAll('[name="closingProof"]:checked').length>3){el.checked=false;toast('Escolha até três provas centrais; os demais documentos continuam nos autos.');}};
T.saveClosing=()=>{const c=iCur(),p=pCur(),g=game(),f=flow(p,c),ids=[...document.querySelectorAll('[name="closingProof"]:checked')].map(x=>x.value),argument=$('closingArgument')?.value.trim()||'',thesis=$('closingThesis')?.value;if(!f.hearingOpened)return toast('As alegações formais são registradas durante a audiência.');if(!ids.length||ids.length>3||argument.length<100)return toast('Escolha de uma a três provas e desenvolva o argumento (mínimo 100 caracteres).');if(!ids.some(id=>!['Cadastro','Certidão','Declaração'].includes(c.evidence.find(e=>e.id===id)?.type)))return toast('Inclua ao menos um registro material; versões e fichas não substituem prova do fato.');let title=thesisChoices(c).find(x=>x[0]===thesis)?.[1];g.closing={thesis,title,evidenceIds:ids,argument,signed:true,day:s.day,cycle:g.cycle};g.drafts.closingArgument=argument;const text=`ALEGAÇÕES FINAIS\nTese: ${title}\nProvas centrais: ${ids.join(', ')}\n${argument}\nPostura: ${g.ethicalChoice||'defesa técnica nos limites dos autos'}`;p.transcript.push({who:s.lawyer,text});doc(p,c,'Alegações finais — construção da tese',text,'Alegações finais');addLog(p,'Alegações finais apresentadas com '+ids.length+' registros centrais.');Audio.fx('stamp');safeRefresh();toast('Tese e provas registradas nas alegações finais.');};
window.closeInstruction=function(){const c=iCur(),p=pCur(),g=game();if(!p||!flow(p,c).hearingOpened)return toast('Abra a audiência antes de concluir a instrução.');if(!g.closing?.signed){goTab('alegacoes');return toast('Construa e registre as alegações finais antes de concluir.');}previous.closeInstruction();if(!p.workflow.hearingOpened){ui.challenge=null;stopClock();Audio.fx('gavel');}};
decision=()=>window.closeInstruction();

function ethicalPanel(c,p){const g=game(c,p);return `<p class="mini">${es(c.ethics?.prompt||'Como sustentar uma posição sem extrapolar os registros?')}</p>${c.ethics?.privateAdmission?`<p class="v4-context">O cliente tem uma informação reservada para discutir com você.</p><button class="btn sm" onclick="T5.consultClient()">Conversa reservada com o cliente</button>`:''}<div class="v5-question-buttons" style="margin-top:14px"><button class="btn ${g.ethicalChoice==='technical'?'primary':''}" onclick="T5.ethics('technical')">Defesa técnica: ${es(c.ethics?.technical||'sustentar os limites da prova.')}</button><button class="btn ${g.ethicalChoice==='candid'?'primary':''}" onclick="T5.ethics('candid')">Postura de reconhecimento: ${es(c.ethics?.candid||'admitir fatos documentados sem renunciar à defesa.')}</button><button class="btn red" onclick="T5.ethics('baseless')">Atribuir a responsabilidade a um terceiro sem prova</button></div><p class="v5-legalnotice">A estratégia é uma escolha do jogo, com efeitos narrativos próprios. Reconhecimento de fatos não cria acordo nem redução de pena automática. Informações reservadas só entram no ato formal quando o cliente autoriza essa postura no roteiro.</p>${g.ethicalChoice?`<span class="tag ${g.ethicalChoice==='baseless'?'red':'green'}">Postura registrada: ${{technical:'defesa técnica',candid:'reconhecimento delimitado',baseless:'acusação sem lastro'}[g.ethicalChoice]}</span>`:''}`;}
T.consultClient=()=>{const c=iCur(),g=game();if(!c.ethics?.privateAdmission)return;g.consulted=true;if(!g.admissionNoted){g.notes+='\n\n[CONVERSA RESERVADA — NÃO JUNTADA]\n'+c.ethics.privateAdmission;g.admissionNoted=true;}store();closeModal();document.body.insertAdjacentHTML('beforeend',`<div class="modalbg" id="docModal"><div class="modal"><div class="eyebrow">SIGILO PROFISSIONAL · ROTEIRO DO CASO</div><h3>Nem tudo foi dito no primeiro atendimento.</h3><div class="v5-dialogue">${es(c.ethics.privateAdmission)}</div><p class="mini">A conversa foi guardada no seu caderno privado. Ela não foi juntada à ata. A autorização narrativa permite escolher uma postura de reconhecimento delimitado.</p><button class="btn primary" onclick="closeModal()">Considerar na estratégia</button></div></div>`);};
T.ethics=choice=>{const c=iCur(),p=pCur(),g=game();if(!['technical','candid','baseless'].includes(choice))return;if(g.ethicalChoice)return toast('A postura deste ciclo já foi registrada; enfrente seus efeitos na argumentação.');if(choice==='candid'&&c.ethics?.privateAdmission&&!g.consulted){T.consultClient();return toast('Leia primeiro a informação reservada e a autorização do cliente.');}g.ethicalChoice=choice;if(choice==='baseless'){g.credibility=Math.max(0,g.credibility-12);s.v5.ethics=Math.max(0,s.v5.ethics-8);g.notes+='\n[REVISAR] Foi escolhida atribuição de responsabilidade sem lastro; isso não estabelece culpa de terceiro.';}else{s.v5.ethics=Math.min(100,s.v5.ethics+2);g.credibility=Math.min(100,g.credibility+2);}if(choice==='candid'&&c.ethics?.privateAdmission&&flow(p,c).hearingOpened){g.admissionDisclosed=true;p.transcript.push({who:s.lawyer,text:'Reconhecimento delimitado, autorizado no roteiro pelo cliente: '+c.ethics.privateAdmission});}addLog(p,'Postura de atuação: '+choice+'; fatos e consequências serão apreciados sem presunção automática.');safeRefresh();toast(choice==='baseless'?'Acusação sem suporte compromete a atuação e não estabelece o fato.':'Postura registrada. O mérito continua sujeito ao conjunto de provas.');};
T.assessment=(c,p)=>{const g=game(c,p),valid=g.connections.filter(x=>x.valid&&p.attached.includes(x.evidenceId)),delta=Math.min(2,Math.floor(valid.length/2))+(g.closing?.signed?1:0)-(g.ethicalChoice==='baseless'?3:0);return {delta,reasons:[`Construção investigativa: ${valid.length} conexões sustentadas por documentos juntados.`,`Alegações finais: ${g.closing?.signed?g.closing.title+'; provas centrais '+g.closing.evidenceIds.join(', '):'não registradas nesta edição'}.`,`A consistência de atuação (${g.credibility}/100) é indicador lúdico e não prova de mérito.`,g.ethicalChoice==='baseless'?'Atribuição de culpa a terceiro sem suporte foi desconsiderada como fato.':'A atuação respeitou os limites narrativos das fontes.']};};
T.disposition=(c,p,result,score)=>{const g=game(c,p);if(score<8||g.ethicalChoice!=='candid'||!g.admissionDisclosed)return result;const n=intCase(c);return ({6:'Reconhecimento delimitado da retirada de R$ 1.200 considerado; o restante da diferença e as consequências jurídicas são apreciados separadamente, preservada a defesa técnica.',14:'Ciência do aviso de proteção pendente considerada no exame dos deveres do engenheiro; autoria, nexo e consequências apreciados nos limites da instrução.',17:'Reconhecimento da condição de não divulgação considerado quanto aos repasses; serviços efetivamente documentados e demais elementos apreciados separadamente.'})[n]||result;};
T.outcomeFor=(c,p,score)=>{const g=game(c,p);return score>=8&&g.ethicalChoice==='candid'&&g.admissionDisclosed&&[6,14,17].includes(intCase(c))?'parcial':score>=14?(c.judgmentPlan?.outcome||'favoravel'):score>=8?'parcial':'desfavoravel';};
function intCase(c){return Number(c.id.slice(-4));}

const upgrades=[{id:'equipment',title:'Estação de análise',cost:2400,desc:'Equipamentos e organização digital reduzem em 20% o custo das novas diligências.'},{id:'intern',title:'Estagiário de pesquisa',cost:1800,desc:'Reduz em dois dias o prazo das novas diligências e prepara síntese dos registros obtidos.'},{id:'library',title:'Acervo processual',cost:1600,desc:'Adiciona um recurso de protesto ao minijogo no início das próximas audiências. As regras processuais não mudam.'}];
const oldOffice=office;
office=function(){return `<div class="eyebrow">O TRABALHO ENTRE AS AUDIÊNCIAS</div><h1>Seu escritório, seu método.</h1><div class="v4-kpi"><span>Caixa: <b>${money(s.cash)}</b></span><span>Postura profissional: <b>${s.v5.ethics}/100</b></span><span>Percepção pública narrativa: <b>${s.v5.publicApproval}/100</b></span></div><section class="panel"><h2>${['Uma sala no Centro','Um escritório consolidado','Um escritório de referência'][s.v5.officeLevel]}</h2><p class="mini">A evolução do espaço aparece na página inicial. Diligências, equipe e especialização formam o ciclo entre novos clientes e audiências.</p>${s.v5.officeLevel<2?`<button class="btn primary" onclick="T5.upgradeOffice()">${s.v5.officeLevel===0?'Ampliar para escritório consolidado — R$ 8.000':'Mudar para sede de referência — R$ 18.000'}</button>`:'<span class="tag green">Sede de referência alcançada</span>'}</section><div class="cols3">${upgrades.map(u=>`<section class="v5-upgrade"><div class="eyebrow">${s.v5.upgrades[u.id]?'ESTRUTURA ATIVA':'INVESTIMENTO DO ESCRITÓRIO'}</div><h3>${u.title}</h3><p>${u.desc}</p><button class="btn ${s.v5.upgrades[u.id]?'':'primary'}" onclick="T5.buy('${u.id}')" ${s.v5.upgrades[u.id]?'disabled':''}>${s.v5.upgrades[u.id]?'✓ Disponível para a equipe':money(u.cost)}</button></section>`).join('')}</div><section class="panel" style="margin-top:20px"><h3>Renome por especialidade</h3><div class="v4-kpi">${AREAS.slice(1).map(a=>`<span>${es(a)} <b>${s.v5.specialties[a]||0}</b></span>`).join('')}</div><p class="mini">Julgamentos concluídos nesta edição desenvolvem renome. Ao atingir 6 pontos numa área, o escritório oferece uma indicação de causa mais complexa dessa especialidade. Todos os 100 casos continuam acessíveis.</p></section>${oldOffice()}`;};
T.buy=id=>{let u=upgrades.find(u=>u.id===id);if(!u||s.v5.upgrades[id])return;if(s.cash<u.cost)return toast('Caixa insuficiente para este investimento.');s.cash-=u.cost;s.v5.upgrades[id]=true;historyLocal('Estrutura adquirida: '+u.title+' por '+money(u.cost)+'.');Audio.fx('stamp');safeRefresh();toast(u.title+' incorporada ao escritório.');};
T.upgradeOffice=()=>{let cost=s.v5.officeLevel===0?8000:18000;if(s.v5.officeLevel>=2)return;if(s.cash<cost)return toast('Caixa insuficiente para a mudança.');s.cash-=cost;s.v5.officeLevel++;historyLocal('Mudança de escritório concluída por '+money(cost)+'.');safeRefresh();};
T.internSummary=()=>{const c=iCur(),p=pCur(),g=game();if(!s.v5.upgrades.intern)return toast('Contrate o estagiário no Escritório para solicitar a síntese.');if(g.internSummaryDone)return toast('A síntese deste caso já está no caderno.');g.internSummaryDone=true;g.notes+='\n\n[SÍNTESE DO ESTAGIÁRIO — REGISTROS OBTIDOS]\n'+available(c,p).slice(2,7).map(e=>e.id+': '+short(e.body,180)).join('\n')+'\nQuestão a verificar: '+c.twist;store();ui.noteOpen=true;drawNotes();toast('Síntese registrada com as fontes, sem concluir por você.');};
T.expert=()=>{const c=iCur(),p=pCur(),e=c.evidence.find(e=>e.type==='Parecer'&&!p.selected.includes(e.id));if(!e)return toast('Os esclarecimentos técnicos previstos já estão disponíveis. Consulte as provas.');goTab('provas');if($('diligenceTarget'))$('diligenceTarget').value=e.id;toast('Esclarecimento técnico selecionado. Confira o custo ao solicitar a diligência.');};
function newsPage(full=true){let arr=s.v5.news.slice(0,full?12:2);return arr.map(n=>`<article class="v5-news"><div class="masthead">O OBSERVADOR · IMPRENSA FICCIONAL</div><h3>${es(n.title)}</h3><p class="mini">${es(n.text)}</p><small class="mini">Dia ${n.day} · Repercussão narrativa do jogo, sem efeito de prova.</small></article>`).join('');}
function rewardDecisions(){for(const c of CASES){const p=s.cases[c.id];if(!p?.decision)continue;let key=c.id+'|'+p.decision.day+'|'+(p.reviewHistory?.length||0);if(s.v5.rewarded.includes(key))continue;s.v5.rewarded.push(key);let g=game(c,p),o=__TRIBUNAL_V4__.outcome(p.decision);s.v5.specialties[c.area]=(s.v5.specialties[c.area]||0)+2+(o==='favoravel'?1:0);s.v5.publicApproval=Math.max(0,Math.min(100,s.v5.publicApproval+(g.ethicalChoice==='baseless'?-4:g.consulted&&o==='favoravel'?-2:1)));s.v5.news.unshift({title:'Decisão em “'+c.title+'” coloca os limites da prova em debate',text:'O escritório encerrou mais um ciclo em '+c.area.toLowerCase()+'. Resultado registrado: '+p.decision.result+'. A repercussão pública é distinta do fundamento jurídico.',day:s.day});s.v5.news=s.v5.news.slice(0,20);Audio.fx('gavel');}}
if(!hasCareer){for(const c of CASES){const p=s.cases[c.id];if(p?.decision)s.v5.rewarded.push(c.id+'|'+p.decision.day+'|'+(p.reviewHistory?.length||0));}}

const glossary={autoria:'Identificação de quem realizou a conduta. Estar no local ou possuir uma conta não demonstra, sozinho, autoria.',materialidade:'Demonstração de que o fato investigado ocorreu. É distinta da identificação do autor.',contraditorio:'Oportunidade de conhecer os elementos do processo e se manifestar sobre eles.',custodia:'Registros que permitem acompanhar preservação, coleta e movimentação de vestígios. Uma falha precisa de análise concreta.',nexo:'Relação entre a conduta ou falha e o resultado alegado. Proximidade temporal não basta por si.',onus:'Responsabilidade processual de demonstrar determinados fatos, conforme o rito e decisões aplicáveis.',proporcionalidade:'Análise da adequação entre necessidade, capacidade e circunstâncias do caso; não é percentual automático.',pronuncia:'Decisão da primeira fase do Júri sobre encaminhamento ao julgamento, sem equivaler a condenação.'};
T.glossary=key=>{closeModal();document.body.insertAdjacentHTML('beforeend',`<div class="modalbg" id="docModal"><div class="modal"><div class="rows between"><h3>Termo jurídico em contexto</h3><button class="btn sm" onclick="closeModal()">Fechar ✕</button></div><p>${es(glossary[key]||'Consulte a biblioteca normativa do jogo.')}</p></div></div>`);};
const previousResearch=research;
research=function(){return `<section class="panel"><div class="eyebrow">CONSULTA RÁPIDA</div><h2>O termo, sem o labirinto.</h2><div class="rows">${Object.keys(glossary).map(k=>`<button class="btn sm v5-term" data-help="${es(glossary[k])}" onclick="T5.glossary('${k}')">${{autoria:'Autoria',materialidade:'Materialidade',contraditorio:'Contraditório',custodia:'Cadeia de custódia',nexo:'Nexo causal',onus:'Ônus da prova',proporcionalidade:'Proporcionalidade',pronuncia:'Pronúncia'}[k]}</button>`).join('')}</div></section>`+previousResearch();};
const oldImport=window.importProgress;
window.importProgress=async function(){const file=$('saveImport')?.files?.[0];if(!file)return toast('Selecione o progresso JSON exportado pelo Tribunal.');try{let v=JSON.parse(await file.text());if(!v.cases||typeof v.cases!=='object')throw Error('Formato');await Promise.all(Object.keys(v.cases).filter(id=>get(id)).map(ready));oldImport();}catch(e){toast('Não foi possível carregar os dossiês do progresso. Confira o arquivo e tente novamente.');}};
decisionPage=function(c,p){let html=previous.decisionPage(c,p);return html+(p.decision?`<section class="panel"><h3>Como você construiu o resultado</h3><div class="v4-kpi"><span>${game(c,p).connections.filter(x=>x.valid).length} conexões sustentadas</span><span>${p.oral?.heard?.length||0} pessoas ouvidas</span><span>${game(c,p).closing?.evidenceIds.length||0} provas nas alegações finais</span></div><p class="mini">O desfecho preserva os limites dos documentos. Consistência e atenção são mecanismos de jogo e não substituem o mérito.</p></section>`:'');};

dossier=function(){const c=iCur(),p=pCur();if(!c||!p)return previous.dossier();game(c,p);if(s.tab==='conexoes')return caseHeader(c,p)+boardPage(c,p);if(s.tab==='pesquisa')return caseHeader(c,p)+searchPage(c,p);if(s.tab==='alegacoes')return caseHeader(c,p)+closingPage(c,p);if(s.tab==='postura')return caseHeader(c,p)+`<section class="panel"><h2>Uma defesa, várias escolhas.</h2>${ethicalPanel(c,p)}</section>`;let html=previous.dossier();if(s.tab==='resumo')html+=`<section class="panel"><div class="rows between"><h3>Recursos de investigação</h3><span class="v5-case-id">CASO INDEPENDENTE · ${c.id}</span></div><div class="rows"><button class="btn" onclick="T5.internSummary()">Solicitar síntese ao estagiário</button><button class="btn" onclick="T5.expert()">Contratar esclarecimento técnico</button><button class="btn" onclick="goTab('postura')">Conversar sobre a estratégia</button></div></section>`;return html;};
const coreRender=render;
render=function(){if(!ui.skipCapture)capture();ui.skipCapture=false;rewardDecisions();coreRender();applyPrefs();const logo=document.querySelector('.logo');if(logo){let glyph=logo.querySelector('i'),sub=logo.querySelector('small');if(glyph)glyph.textContent='§';if(sub)sub.textContent='ENTRE FATOS E VERSÕES';}const top=document.querySelector('.topbar');if(top&&!$('v5Toolbar'))top.insertAdjacentHTML('beforeend',`<div class="v5-railtools" id="v5Toolbar"><button class="v5-iconbtn ${s.v5.sound?'active':''}" title="Efeitos sonoros" aria-label="Alternar efeitos sonoros" data-no-sound onclick="T5.toggleSound()">${s.v5.sound?'Som · on':'Som · off'}</button><button class="v5-iconbtn" onclick="T5.notes()" ${!pCur()?'disabled':''}>Caderno</button><button class="v5-iconbtn" title="Acessibilidade e preferências" onclick="T5.settings()">Ajustes</button></div>`);if(s.view==='inicio'){const referral=CASES.find(c=>(s.v5.specialties[c.area]||0)>=6&&c.difficulty>=4&&!s.cases[c.id]);if(referral)document.querySelector('.v5-home')?.insertAdjacentHTML('beforeend',`<section class="panel" style="margin-top:24px"><div class="eyebrow">INDICAÇÃO POR ESPECIALIZAÇÃO</div><h3>Seu renome em ${es(referral.area)} trouxe uma nova causa.</h3><p class="mini">${es(referral.title)} · Complexidade ${referral.difficulty}. Você pode consultar a pasta antes de aceitar.</p><button class="btn primary" onclick="accept('${referral.id}')">Examinar a indicação ↗</button></section>`);}const footer=document.querySelector('.footer');if(footer)footer.textContent='TRIBUNAL V · ENTRE FATOS E VERSÕES · Obra de ficção jurídica · Autoria Hevvy Calazaes';restore();if(ui.noteOpen)drawNotes();requestAnimationFrame(()=>{drawBoard();animateDialogue();});store();};
document.addEventListener('keydown',e=>{const modal=document.querySelector('#docModal .modal');if(e.key==='Escape'){if(modal)closeModal();else if(ui.noteOpen)T.notes();return;}if(e.key==='Tab'&&modal){const controls=[...modal.querySelectorAll('button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),a[href]')];if(!controls.length)return;let first=controls[0],last=controls.at(-1);if(!modal.contains(document.activeElement)){e.preventDefault();first.focus();}else if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
new MutationObserver(records=>{for(const r of records)for(const node of r.addedNodes)if(node.nodeType===1&&node.classList.contains('modalbg')){const modal=node.querySelector('.modal');modal?.setAttribute('role','dialog');modal?.setAttribute('aria-modal','true');}}).observe(document.body,{childList:true});
T.debug={game,shortAnswer,flow,drawBoard,ready,ui};
refresh();
})();
